right:
@import 'c/ihStyles';

.input-row {
    display: flex;
    align-items: flex-end;
    gap: 12px;
}
.input {
    flex: 1 1 auto;
}
.hint {
    margin: 6px 0 16px;
}
.cols {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: 20px;
    align-items: start;
}
.col {
    min-width: 0;
}
.sec-head {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: 8px;
    margin-bottom: 6px;
}
.sec-title {
    margin: 0;
    font-size: 14px;
    font-weight: 700;
    color: var(--ih-ink-2);
}
.copy {
    background: none;
    border: 0;
    padding: 0;
    font: inherit;
    font-size: 13px;
    color: var(--ih-brand);
    cursor: pointer;
}
.copy:hover {
    text-decoration: underline;
}
.copy:focus-visible {
    outline: 2px solid var(--ih-brand);
    outline-offset: 2px;
}
.gap {
    display: block;
    margin-top: 14px;
}
.gap-s {
    display: block;
    margin-top: 8px;
}
.words {
    margin: 6px 0 0;
    color: var(--ih-ink-2);
}
.grid {
    width: 100%;
    border-collapse: collapse;
    font-size: 13px;
}
.grid th,
.grid td {
    border: 1px solid var(--ih-line);
    padding: 7px 10px;
    text-align: left;
    vertical-align: top;
    overflow-wrap: anywhere;
}
.grid th {
    background: #fafaf9;
    font-weight: 700;
}
